                throw new \InvalidArgumentException(sprintf('The options "enqueue" and "from_bus" cannot be set together when handling the "%s" message.', get_class($message)));
            }

            if (!empty($options['from_bus'])) {
                $this->dispatchToBus($message, $options, $descriptor);

                continue;
            }

            if (empty($options['bus']) || \count($listeners) !== 1) {
                $this->callHandler($descriptor, $message, $options);

                continue;
            }

            $this->dispatchToBus($message, $options, $descriptor);
        }

        $next->handle($envelope);
    }

    private function callHandler(HandlerDescriptor $descriptor, $message, array $options): void
    {
        $callables = $this->resolveCallables($descriptor);
        foreach ($callables as $callable) {
            if (!is_callable($callable)) {
                throw new \InvalidArgumentException(sprintf('The "getHandlers" method must select a callable for message "%s".', get_class($message)));
