                unset($options['bus'], $options['from_bus'], $options['enqueue']);

                $responder = is_array($callable) ? new \Closure($callable[0], $callable[1]) : $callable;

                $responder($message, $options);
            };

            $callHandler($message, $options);
        }
    }

    private function resolveCallables(HandlerDescriptor $descriptor): array
    {
        $callable = $descriptor->getCallable();

        if (\is_string($callable) && \function_exists($callable)) {
            return [$callable];
        }

        if (\is_array($callable)) {
            return [$callable];
        }

        if ($callable instanceof \Closure) {
            return [$callable];
        }

        throw new \InvalidArgumentException(sprintf('The resolver can only deal with functions, arrays or closures.'));
    }

